        <th>{row.name}</th><td><GtInternalTranslateJsx>Cell {<GtInternalVar>{(enabled ? <Box><GtInternalTranslateJsx>Question {<GtInternalVar>{account.name}</GtInternalVar>}</GtInternalTranslateJsx></Box> : <Box>{fallback}</Box>) satisfies React.ReactNode}</GtInternalVar>}</GtInternalTranslateJsx></td>
        <td><Card render={({
                  active
                }) => active ? <b><GtInternalTranslateJsx>Active {<GtInternalVar>{(enabled ? <Box><GtInternalTranslateJsx>Question {<GtInternalVar>{account.name}</GtInternalVar>}</GtInternalTranslateJsx></Box> : <Box>{fallback}</Box>) satisfies React.ReactNode}</GtInternalVar>}</GtInternalTranslateJsx></b> : <Value>{row.raw}</Value>} /></td>
      </tr>{row.children?.map(child => <tr key={child.id}><td colSpan={index + 1}><GtInternalTranslateJsx>Nested {<GtInternalVar>{child.name}</GtInternalVar>}</GtInternalTranslateJsx></td></tr>)}</Fragment>)}
    </tbody></table></Shell>;
  },
  get empty() {
    return <p><GtInternalTranslateJsx>Independent getter page</GtInternalTranslateJsx></p>;
  }
};
